// Users.tsx

import React, { useState, useEffect } from "react";
import { useUsers } from "../hooks/useUsers";
import { fetchUsers } from "../api/userServices";
import { UserTable } from "../components/Table";

export interface User {
  id: string;
  first_name: string | null;
  last_name: string | null;
  image_url: string | null;
  about_me: string | null;
  professional_headline: string | null;
  location_allowed: boolean | null;
  certifications: string[];
  location_id: string[];
  user_type_id: string[];
  skills_id: string[];
  profile_attachments: string[];
  phone: string | null;
  created_at: string | null;
  updated_at: string | null;

  // Computed display helpers (derived — not stored in DB)
  name: string;       // `${first_name} ${last_name}`.trim()
  location: string;   // first entry of location_id, or "—"
}

const Users: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);

  const {
    searchTerm,
    setSearchTerm,
    filteredAndSortedUsers,
    requestSort,
    sortConfig,
  } = useUsers(users);

  useEffect(() => {
    fetchUsers().then((data) => {
      setUsers(data as User[]);
    });
  }, []);

  return (
    <div
      style={{
        width: "100%",
        display: "flex",
        flexDirection: "column",
        gap: 20,
      }}
    >
      {/* HEADER */}
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: 12,
        }}
      >
        <input
          type="text"
          placeholder="Search users..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          style={{
            padding: "10px 14px",
            borderRadius: 10,
            border: "1px solid #CBD5E1",
            width: 280,
            maxWidth: "100%",
            outline: "none",
            fontSize: 14,
          }}
        />
      </div>

      {/* TABLE */}
      <UserTable
        data={filteredAndSortedUsers}
        onSort={requestSort}
        sortConfig={sortConfig}
        columns={[
          { label: "Name",     key: "name" },
          { label: "Headline", key: "professional_headline" },
          { label: "Phone",    key: "phone" },
          { label: "Location", key: "location" },
        ]}
      />
    </div>
  );
};

export default Users;
